class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path in ("/", "/index.html"):
            body = HTML.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        else:
            self.send_error(404, "Not found")

    def log_message(self, fmt, *args):
        print("[%s] %s" % (self.address_string(), fmt % args))


def main():
    parser = argparse.ArgumentParser(description="Banque Misr Virtual Assistant UI")
    parser.add_argument("--port", type=int, default=8000, help="port to serve on (default 8000)")
    parser.add_argument("--save", metavar="FILE", help="write the HTML to FILE and exit")
    parser.add_argument("--no-browser", action="store_true", help="don't open a browser automatically")
    args = parser.parse_args()

    if args.save:
        with open(args.save, "w", encoding="utf-8") as f:
            f.write(HTML)
        print(f"Saved to {args.save}")
        return

    url = f"http://localhost:{args.port}/"
    server = HTTPServer(("127.0.0.1", args.port), Handler)
    print(f"Serving Banque Misr Virtual Assistant at {url}  (Ctrl+C to stop)")
    if not args.no_browser:
        threading.Timer(0.5, lambda: webbrowser.open(url)).start()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nStopped.")
        server.server_close()


if __name__ == "__main__":
    main()
